139	
140			for (ShardMeta shardMeta : clusterMeta.getShards().values()) {
141				for (KeeperMeta keeperMeta : shardMeta.getKeepers()) {
142					addKeeper(clusterMeta.getId(), shardMeta.getId(), keeperMeta);
143				}
144			}
145		}
