	/**
	 * for primary dc, keeper's master should be a redis of the shard;
	 * for backup dc, keeper's master should not be a redis of the shard.
	 *
	 * When a datacenter migration is in progress the keeper master no longer matches the current meta,
	 * so this returns false and correction commands are suppressed.
	 */
	private boolean isCurrentMetaKeeperMasterMatch(String clusterId, String shardId) {
		Pair<String, Integer> keeperMaster = currentMetaManager.getKeeperMaster(clusterId, shardId);
		if (keeperMaster == null) {
			return false;
		}
		if (metaCache.isCurrentDcPrimary(clusterId)) {
			return isKeeperMasterRedis(clusterId, shardId, keeperMaster);
		} else {
			return !isKeeperMasterRedis(clusterId, shardId, keeperMaster);
		}
	}

	private boolean isKeeperMasterRedis(String clusterId, String shardId, Pair<String, Integer> keeperMaster) {
		List<RedisMeta> redises = metaCache.getShardRedises(clusterId, shardId);
		if (redises == null) {
			return false;
		}
		for (RedisMeta redis : redises) {
			if (ObjectUtils.equals(redis.getIp(), keeperMaster.getKey())
					&& ObjectUtils.equals(redis.getPort(), keeperMaster.getValue())) {
				return true;
			}
		}
		return false;
